# transformations compare src and output with proper 9x10 bounding
src={(2,5),(3,3),(3,4),(3,5),(3,7),(4,3),(5,3),(5,4),(5,5),(5,6),(6,2),(6,6)}
out={(2,5),(3,2),(3,3),(4,3),(4,5),(4,6),(5,3),(5,5),(6,3),(6,4),(6,5),(7,2)}
transforms={}
for refl in [False,True]:
 for rot in range(4):
  def f(r,c,refl=refl,rot=rot):
   h,w=9,10
   if refl: c=w-1-c
   for _ in range(rot): r,c=c,h-1-r; h,w=w,h
   return r,c
  s={f(r,c) for r,c in src}
  transforms[(refl,rot)]=(len(s&out),len(s),s)
[(k,v[:2]) for k,v in transforms.items()]
